def walk(v,path='$'):
 yield path,v
 if isinstance(v,dict):
  for k,x in v.items():yield from walk(x,path+'.'+k)
 elif isinstance(v,list):
  for i,x in enumerate(v):yield from walk(x,f'{path}[{i}]')
def category(path):
 if any(x in path for x in ['summary','coverage','inputs','rules','dictionary','dictionaries','glossary','reading','inheritance','value_dictionary']):return '계약·사전·조회 파생'
 if any(x in path for x in ['conflict','resolved','node_slots','reconcile']):return 'resolution·상충'
 if any(x in path for x in ['decision','judgement','changes','delta','questions','open','stale','not_done','fix']):return 'decision·작업상태'
 if any(x in path for x in ['correspondence','ledger','product_family','product_links','strings','expressions','deferred','handoff','market','non_packages']):return 'mapping·행선지'
 if any(x in path for x in ['claims','records','extracted','attrs','side_effect','pih','timeline','family_text','notes','dose_range']):return 'claim·원문·attachment'
 if any(x in path for x in ['edges','contains','slots','related','family_defaults']):return '관계·구성'
 return '엔터티·중첩 속성'
